}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(100%);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-slide-up {
  animation: slideUp 0.5s ease-out;
}

@keyframes gradientShift {
  0%, 100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

.animate-gradient {
  background-size: 200% 200%;
  animation: gradientShift 8s ease infinite;
}

@keyframes float {
  0%, 100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-10px);
  }
}

.animate-float {
  animation: float 3s ease-in-out infinite;
}

@keyframes shimmer {
  0% {
    background-position: -1000px 0;
  }
  100% {
    background-position: 1000px 0;
  }
}

.animate-shimmer {
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
  background-size: 1000px 100%;
  animation: shimmer 2s infinite;
}

/* Focus and accessibility */
.focus-ring {
  @apply focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2;
}

/* Smooth scrolling */
html {
  scroll-behavior: smooth;
}

/* Remove any dark/black elements */
.no-dark {
  @apply bg-white text-neutral-700;
}

/* Modal overlays - light instead of black */
.modal-overlay {
  background-color: rgba(248, 250, 252, 0.8);
  backdrop-filter: blur(4px);
}

/* Mobile-optimized components */
.mobile-button {
  @apply w-full sm:w-auto text-center min-h-[48px] px-6 py-3 text-base font-semibold touch-manipulation;
  /* Prevent button text selection and improve touch response */
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.mobile-card {
  @apply p-4 sm:p-6 lg:p-8;
  /* Ensure proper stacking and no overflow issues */
  position: relative;
  overflow: hidden;
}

.mobile-spacing {
  @apply space-y-4 sm:space-y-6;
}

/* Button Container to prevent overlapping */
.button-container {
  @apply flex flex-col sm:flex-row gap-3 sm:gap-4 items-stretch sm:items-center justify-center w-full;
}

/* Mobile Layout Fixes */
.mobile-container {
  @apply px-4 sm:px-6 lg:px-8;
  max-width: 100vw;
  overflow-x: hidden;
}

/* Tax Calculator Mobile Focus */
.tax-calc-mobile {
  @apply bg-gradient-to-br from-blue-50 to-indigo-100 p-6 sm:p-8 rounded-2xl border-2 border-primary border-opacity-20 shadow-lg;
}

/* Custom animations and transitions */
.card-hover {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.card-hover:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 40px rgba(59, 130, 246, 0.15), 0 10px 20px rgba(59, 130, 246, 0.1);
}

/* Modern Gradients */
.gradient-blue {
  background: linear-gradient(135deg, hsl(214, 65%, 56%) 0%, hsl(217, 91%, 60%) 100%);
}

.gradient-blue-light {
  background: linear-gradient(135deg, hsl(214, 65%, 96%) 0%, hsl(217, 91%, 95%) 100%);
}

.gradient-mesh {
  background: 
    radial-gradient(at 0% 0%, hsla(214, 65%, 56%, 0.2) 0px, transparent 50%),
    radial-gradient(at 100% 0%, hsla(262, 83%, 58%, 0.15) 0px, transparent 50%),
    radial-gradient(at 100% 100%, hsla(217, 91%, 60%, 0.2) 0px, transparent 50%),
    radial-gradient(at 0% 100%, hsla(142, 76%, 36%, 0.15) 0px, transparent 50%);
}

.gradient-text {
  background: linear-gradient(135deg, hsl(214, 65%, 56%) 0%, hsl(262, 83%, 58%) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.market-card {
  background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #e2e8f0;
}

.market-card:hover {
  background: linear-gradient(135deg, #ffffff 0%, #f0f9ff 100%);
  border-color: hsl(var(--primary-blue));
}

/* Loading animation */
@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.animate-spin {
  animation: spin 1s linear infinite;
}

/* Button transitions */
.btn-transition {
  transition: all 0.2s ease-in-out;
}

.btn-transition:hover {
  transform: translateY(-1px);
}

/* Modern spacing utilities */
.container-padding {
  @apply px-4 md:px-6 lg:px-8;
}

.max-container {
  @apply max-w-7xl mx-auto;
}

