      self_occupied_loss: 0,
      let_out_income: 0,
      total_house_property: 0
    },
    business_profession_income: {
      gross_receipts: 0,
      expenses: 0,
      net_profit: 0
    },
    capital_gains: {
      short_term: 0,
      long_term: 0,
      crypto_gains: 0,
      total_capital_gains: 0
    },
    other_income: {
      interest_income: 0,
      dividends: 0,
      lottery_winnings: 0,
      foreign_income: 0,
      other: 0
    },
    deductions: {
      "80C": 0,
      "80CCC": 0,
      "80CCD1": 0,
      "80CCD1B": 0,
      "80CCD2": 0,
      "80D": 0,
      "80E": 0,
      "80G": 0,
      "80TTA": 0,
      other: 0,
