    doc.line(20, y, pageWidth - 20, y);
    y += 8;

    doc.setFontSize(8);
    doc.setTextColor(120, 120, 120);
    doc.text('Generated by AiTaxBot (https://aitaxbot.in)', pageWidth / 2, y, { align: 'center' });
    y += 4;
