#!/usr/bin/env python3
"""
PDF Processing Service for AiTaxBot
Handles extraction of tax data from Form 16, AIS, and 26AS documents
"""

import json
import sys
import re
import pdfplumber
from decimal import Decimal
from typing import Dict, Optional, Any
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class TaxDocumentProcessor:
    """Main class for processing tax documents"""

    def __init__(self):
        self.form16_patterns = {
            'gross_salary': [
                r'Total.*?Rs\.?\s*(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'Gross Salary.*?Rs\.?\s*(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'1\(d\).*?Total.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'standard_deduction': [
                r'Standard deduction under section 16\(ia\).*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'4\(a\).*?Standard deduction.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'deductions_80c': [
                r'section 80C.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'10\(d\).*?Total deduction under section 80C.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'deductions_80d': [
                r'section 80D.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'health insurance.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'total_deductions': [
                r'Aggregate of deductible amount under Chapter VI-A.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'11\..*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'taxable_income': [
                r'Total taxable income.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'12\..*?Total taxable income.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'tax_liability': [
                r'Tax on total income.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'13\..*?Tax on total income.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'tds_deducted': [
                r'Total tax deducted.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)',
                r'TDS.*?(\d{1,3}(?:,\d{3})*(?:\.\d{2})?)'
            ],
            'assessment_year': [
                r'Assessment Year.*?(\d{4}-\d{2})',
                r'AY.*?(\d{4}-\d{2})'
            ],
            'employee_pan': [
                r'PAN of the Employee.*?([A-Z]{5}\d{4}[A-Z])',
                r'Employee.*?PAN.*?([A-Z]{5}\d{4}[A-Z])'
            ],
            'employer_pan': [
                r'PAN of the Deductor.*?([A-Z]{5}\d{4}[A-Z])',
                r'Deductor.*?PAN.*?([A-Z]{5}\d{4}[A-Z])'
            ],
            'employer_tan': [
                r'TAN of the Deductor.*?([A-Z]{4}\d{5}[A-Z])',
                r'TAN.*?([A-Z]{4}\d{5}[A-Z])'
            ]
        }

    def extract_text_from_pdf(self, file_path: str) -> str:
        """Extract text from PDF file"""
        try:
            text = ""
            with pdfplumber.open(file_path) as pdf:
                for page in pdf.pages:
                    page_text = page.extract_text()
                    if page_text:
                        text += page_text + "\n"
            return text
        except Exception as e:
            logger.error(f"Error extracting text from PDF: {str(e)}")
            raise

    def clean_amount(self, amount_str: str) -> Optional[Decimal]:
        """Clean and convert amount string to Decimal"""
        if not amount_str:
            return None

        # Remove commas and convert to decimal
        cleaned = re.sub(r'[,\s]', '', amount_str)
        try:
            return Decimal(cleaned)
        except:
            return None

    def extract_form16_data(self, text: str) -> Dict[str, Any]:
        """Extract data from Form 16 document"""
        extracted_data = {}

        # Extract each field using patterns
        for field, patterns in self.form16_patterns.items():
            for pattern in patterns:
                match = re.search(pattern, text, re.IGNORECASE | re.DOTALL)
                if match:
                    value = match.group(1).strip()

                    # Handle different field types
                    if field in ['assessment_year', 'employee_pan', 'employer_pan', 'employer_tan']:
                        extracted_data[field] = value
                    else:
                        # Convert to decimal for amounts
                        decimal_value = self.clean_amount(value)
                        if decimal_value is not None:
                            extracted_data[field] = str(decimal_value)
                    break

        # Extract employer name (more complex pattern)
        employer_patterns = [
            r'Name and address of the Employer.*?\n\s*([^\n]+)',
            r'Employer.*?\n\s*([A-Z\s&.]+)'
        ]

        for pattern in employer_patterns:
            match = re.search(pattern, text, re.IGNORECASE | re.DOTALL)
            if match:
                employer_name = match.group(1).strip()
                if len(employer_name) > 3:  # Basic validation
                    extracted_data['employer_name'] = employer_name
                break

        # Calculate derived fields
        self._calculate_derived_fields(extracted_data)

        return extracted_data

    def _calculate_derived_fields(self, data: Dict[str, Any]):
        """Calculate derived fields like refund/tax due"""
        try:
            tax_liability = Decimal(data.get('tax_liability', '0'))
            tds_deducted = Decimal(data.get('tds_deducted', '0'))

            # Calculate refund due or tax payable
            difference = tds_deducted - tax_liability
            if difference > 0:
                data['refund_due'] = str(difference)
            else:
                data['tax_payable'] = str(abs(difference))

        except Exception as e:
            logger.warning(f"Error calculating derived fields: {str(e)}")

    def process_document(self, file_path: str, document_type: str) -> Dict[str, Any]:
        """Main method to process tax documents"""
        try:
            # Extract text from PDF
            text = self.extract_text_from_pdf(file_path)

            if not text.strip():
                raise ValueError("No text could be extracted from the PDF")

            # Process based on document type
            if document_type.lower() == 'form16':
                extracted_data = self.extract_form16_data(text)
            elif document_type.lower() == 'ais':
                extracted_data = self.extract_ais_data(text)
            elif document_type.lower() == '26as':
                extracted_data = self.extract_26as_data(text)
            else:
                raise ValueError(f"Unsupported document type: {document_type}")

            return {
                'success': True,
                'data': extracted_data,
                'message': f'Successfully extracted data from {document_type}'
            }

        except Exception as e:
            logger.error(f"Error processing document: {str(e)}")
            return {
                'success': False,
                'data': {},
                'error': str(e)
            }

    def extract_ais_data(self, text: str) -> Dict[str, Any]:
        """Extract data from AIS document (placeholder for now)"""
        # AIS processing logic will be implemented here
        return {
            'document_type': 'ais',
            'message': 'AIS processing will be implemented in next phase'
        }

    def extract_26as_data(self, text: str) -> Dict[str, Any]:
        """Extract data from 26AS document (placeholder for now)"""
        # 26AS processing logic will be implemented here
        return {
            'document_type': '26as',
            'message': '26AS processing will be implemented in next phase'
        }

def main():
    """Main function to handle command line execution"""
    if len(sys.argv) != 3:
        print(json.dumps({
            'success': False,
            'error': 'Usage: python pdfProcessor.py <file_path> <document_type>'
        }))
        sys.exit(1)

    file_path = sys.argv[1]
    document_type = sys.argv[2]

    processor = TaxDocumentProcessor()
    result = processor.process_document(file_path, document_type)

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

