import { apiRequest } from "@/lib/queryClient";

export interface MarketIndex {
  symbol: string;
  name: string;
  value: number;
  change: number;
  changePercent: number;
  lastUpdated: Date;
}

export interface MutualFund {
  schemeCode: string;
  schemeName: string;
  nav?: string;
  date?: string;
}

export interface NewsArticle {
  title: string;
  summary?: string;
  url?: string;
  source?: string;
  publishedAt?: string;
  category?: string;
  sentiment?: string;
  urlToImage?: string;
}

export class FinancialAPIService {
  // Market Indices
  static async getMarketIndices(): Promise<MarketIndex[]> {
    const response = await apiRequest("GET", "/api/market-indices");
    return response.json();
  }

  // Mutual Funds
  static async getMutualFunds(): Promise<MutualFund[]> {
    const response = await apiRequest("GET", "/api/external/mutual-funds");
    return response.json();
  }

  static async getMutualFund(code: string): Promise<any> {
    const response = await apiRequest("GET", `/api/external/mutual-funds/${code}`);
    return response.json();
  }

  // Alpha Vantage API
  static async getAlphaVantageData(func: string, symbol: string, interval?: string): Promise<any> {
    const params = new URLSearchParams({
      function: func,
      symbol,
      ...(interval && { interval })
    });

    const response = await apiRequest("GET", `/api/external/alpha-vantage?${params}`);
    return response.json();
  }


  // News API
  static async getMarketNews(category = "business", country = "in"): Promise<{ articles: NewsArticle[] }> {
    const params = new URLSearchParams({
      category,
      country
    });

    const response = await apiRequest("GET", `/api/external/news?${params}`);
    return response.json();
  }

  // Indian Stock Market (via Alpha Vantage)
  static async getIndianStockData(symbol: string): Promise<any> {
    // For Indian stocks, append .BSE or .NSE
    const indianSymbol = symbol.includes('.') ? symbol : `${symbol}.BSE`;
    return this.getAlphaVantageData('TIME_SERIES_DAILY', indianSymbol);
  }

  // US Market Data
  static async getUSStockData(symbol: string): Promise<any> {
    return this.getAlphaVantageData('TIME_SERIES_DAILY', symbol);
  }
}

client/src/components/ui/last-updated.ts.content:
import React from "react";
import { Clock, CheckCircle, TrendingUp } from "lucide-react";

interface LastUpdatedProps {
  date: string | Date;
  type?: "content" | "data" | "rates";
  className?: string;
  showIcon?: boolean;
}

export function LastUpdated({ 
  date, 
  type = "content",
  className = "",
  showIcon = true 
}: LastUpdatedProps) {
  const formatDate = (date: string | Date) => {
    const dateObj = typeof date === 'string' ? new Date(date) : date;
    return dateObj.toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const getTypeInfo = () => {
    switch (type) {
      case "data":
        return {
          label: "Data updated",
          icon: <TrendingUp className="w-3 h-3" />,
          color: "text-blue-600"
        };
      case "rates":
        return {
          label: "Tax rates updated",
          icon: <CheckCircle className="w-3 h-3" />,
          color: "text-green-600"
        };
      default:
        return {
          label: "Last updated",
          icon: <Clock className="w-3 h-3" />,
          color: "text-neutral-500"
        };
    }
  };

  const typeInfo = getTypeInfo();

  return (
    <div 
      className={`flex items-center space-x-1 text-xs ${typeInfo.color} ${className}`}
      data-testid={`last-updated-${type}`}
    >
      {showIcon && typeInfo.icon}
      <span>
        {typeInfo.label}: {formatDate(date)}
      </span>
    </div>
  );
}

export default LastUpdated;

client/src/components/ui/modal.tsx.content:
import { ReactNode } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
  size?: "sm" | "md" | "lg" | "xl" | "2xl" | "4xl" | "6xl";
}

export default function Modal({ isOpen, onClose, title, children, size = "4xl" }: ModalProps) {
  if (!isOpen) return null;

  const sizeClasses = {
    sm: "max-w-sm",
    md: "max-w-md",
    lg: "max-w-lg",
    xl: "max-w-xl", 
    "2xl": "max-w-2xl",
    "4xl": "max-w-4xl",
    "6xl": "max-w-6xl"
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
      <Card className={`bg-white rounded-xl ${sizeClasses[size]} w-full max-h-[90vh] overflow-y-auto`}>
        <div className="p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-900">{title}</h2>
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              className="text-gray-500 hover:text-gray-700"
              data-testid="button-close-modal"
            >
              <i className="fas fa-times text-xl"></i>
            </Button>
          </div>
          {children}
        </div>
      </Card>
    </div>
  );
}

